#include <iostream>
#include <cstdint>
#include <iomanip>
#include <cuda_runtime.h>
#include <device_launch_parameters.h>
#include <cmath>
#include <algorithm>

// Include the T-Tables generated by the Python script
// Expected definition: __device__ const uint64_t T_TABLE[8][256] = { ... };
#include "tables_SKINNY.inc"

__device__ int d_found = 0;
__device__ uint64_t d_found_key = 0;

__constant__ uint64_t c_rc_packed[32];

__global__ void skinny_bruteforce_table_kernel(
    uint64_t pt,
    uint64_t ct,
    uint64_t offset,
    unsigned int exhaustive_loops)
{
    if (d_found) return;

    __shared__ uint64_t s_T[8][256];
    int l_tid = threadIdx.x;
    if (l_tid < 256) {
#pragma unroll
        for (int i = 0; i < 8; ++i) {
            s_T[i][l_tid] = T_TABLE[i][l_tid];
        }
    }
    __syncthreads();

    uint32_t base_tid = blockIdx.x * blockDim.x + threadIdx.x;
    uint32_t stride = gridDim.x * blockDim.x;

    for (unsigned int j = 0; j < exhaustive_loops; j++) {
        uint64_t tk = offset + (uint64_t)base_tid + (uint64_t)j * stride;

        uint64_t rk[32];
        uint32_t tk_top = (uint32_t)(tk >> 32);
        uint32_t tk_bot = (uint32_t)(tk & 0xFFFFFFFF);

#pragma unroll
        for (int r = 0; r < 32; r++) {
            rk[r] = ((uint64_t)tk_top << 32) ^ c_rc_packed[r];

            uint32_t new_top =
                ((tk_bot & 0x0F0000F0) << 4) | 
                ((tk_bot & 0xF0F0F000) >> 8) |
                ((tk_bot & 0x0000000F) << 24) | 
                ((tk_bot & 0x00000F00) << 8) | 
                ((tk_bot & 0x000F0000) >> 16);  

            tk_bot = tk_top;
            tk_top = new_top;
        }

        uint64_t state = pt;

#pragma unroll
        for (int rnd = 0; rnd < 32; ++rnd) {
            state ^= rk[rnd];

            uint64_t next =
                s_T[0][(state >> 56) & 0xFF] ^
                s_T[1][(state >> 48) & 0xFF] ^
                s_T[2][(state >> 40) & 0xFF] ^
                s_T[3][(state >> 32) & 0xFF] ^
                s_T[4][(state >> 24) & 0xFF] ^
                s_T[5][(state >> 16) & 0xFF] ^
                s_T[6][(state >> 8) & 0xFF] ^
                s_T[7][(state) & 0xFF];

            state = next;
        }

        if (state == ct) {
            if (atomicExch(&d_found, 1) == 0) {
                d_found_key = tk;
            }
        }
    }
}

void precompute_and_load_rc() {
    const uint8_t rc[32] = {
        0x01,0x03,0x07,0x0F,0x1F,0x3E,0x3D,0x3B,0x37,0x2F,0x1E,0x3C,0x39,0x33,0x27,0x0E,
        0x1D,0x3A,0x35,0x2B,0x16,0x2C,0x18,0x30,0x21,0x02,0x05,0x0B,0x17,0x2E,0x1C,0x38
    };

    uint64_t h_rc_packed[32];
    for (int r = 0; r < 32; r++) {
        uint64_t c = rc[r];
        uint64_t c0 = c & 0xF; 
        uint64_t c1 = c >> 4;   
        uint64_t c2 = 0x2;      
        h_rc_packed[r] = (c0 << 60) | (c1 << 44) | (c2 << 28);
    }

    cudaMemcpyToSymbol(c_rc_packed, h_rc_packed, sizeof(h_rc_packed));
}

int main() {
    cudaSetDeviceFlags(cudaDeviceMapHost);

    uint64_t pt = 0x1122334455667788ULL;
    uint64_t ct = 0x22ff30d498ea62d7ULL; 

    int power = 32; 
    uint64_t total_keys = 1ULL << power;
    uint64_t KEYS_PER_BATCH = 1ULL << 28; 

    unsigned int threads_per_block = 256;

    std::cout << " [SKINNY-64/64] GPU CUDA Table-Based Bruteforcer\n";
    std::cout << " Key Space     : 2^" << power << "\n";
    std::cout << " Threads/Block : " << threads_per_block << "\n";

    cudaDeviceSetSharedMemConfig(cudaSharedMemBankSizeEightByte);
    precompute_and_load_rc();

    cudaStream_t stream;
    cudaStreamCreate(&stream);

    cudaEvent_t start, stop;
    cudaEventCreate(&start);
    cudaEventCreate(&stop);

    int host_found = 0;
    uint64_t host_found_key = 0;
    cudaMemcpyToSymbol(d_found, &host_found, sizeof(int));

    cudaEventRecord(start, stream);

    for (uint64_t offset = 0; offset < total_keys; offset += KEYS_PER_BATCH) {
        cudaMemcpyFromSymbolAsync(&host_found, d_found, sizeof(int), 0, cudaMemcpyDeviceToHost, stream);
        cudaStreamSynchronize(stream);
        if (host_found) break;

        uint64_t current_batch_keys = std::min(KEYS_PER_BATCH, total_keys - offset);

        unsigned int blocks_per_grid = 1;
        unsigned int exhaustive_loops = 1;
        unsigned long long grids = current_batch_keys / threads_per_block;

        if (grids > 65536) {
            blocks_per_grid = 65536;
            exhaustive_loops = (unsigned int)(grids / blocks_per_grid);
        }
        else {
            blocks_per_grid = (unsigned int)(grids > 0 ? grids : 1);
        }

        skinny_bruteforce_table_kernel << <blocks_per_grid, threads_per_block, 0, stream >> > (
            pt, ct, offset, exhaustive_loops
            );
    }

    cudaEventRecord(stop, stream);
    cudaEventSynchronize(stop);

    float elapsed_ms = 0;
    cudaEventElapsedTime(&elapsed_ms, start, stop);
    double elapsed_sec = elapsed_ms / 1000.0;
    double keys_per_sec = total_keys / elapsed_sec;
    double speed_power = std::log2(keys_per_sec);

    cudaMemcpyFromSymbol(&host_found, d_found, sizeof(int));
    if (host_found) {
        cudaMemcpyFromSymbol(&host_found_key, d_found_key, sizeof(uint64_t));
        std::cout << " Result        : Key = 0x" << std::hex << std::setw(16) << std::setfill('0')
            << std::uppercase << host_found_key << std::dec << "\n";
    }
    else {
        std::cout << " Result        : Key not found\n";
    }

    std::cout << " Time          : " << std::fixed << std::setprecision(6) << elapsed_sec << " sec\n";
    std::cout << " Max Speed     : 2^" << std::fixed << std::setprecision(2) << speed_power << " keys/sec\n";

    cudaStreamDestroy(stream);
    cudaEventDestroy(start);
    cudaEventDestroy(stop);

    return 0;
}   